        lockButton=button("",()->{if(!busy)camera.unlockMetering();});lockButton.setTextColor(AMBER);lockButton.setVisibility(View.GONE);lockButton.setContentDescription("解除对焦和曝光锁定");FrameLayout.LayoutParams lockLayout=new FrameLayout.LayoutParams(-2,dp(48),Gravity.TOP|Gravity.CENTER_HORIZONTAL);lockLayout.topMargin=dp(10);finder.addView(lockButton,lockLayout);
