        LinearLayout filmShelf=row();filmGroupButton=new FilmGroupWheel(this);filmGroupButton.listener=this::selectFilmGroup;filmGroupButton.setOnClickListener(v->showFilmGroups());add(filmShelf,filmGroupButton,48,64);filmWheel=new FilmWheel(this);filmWheel.listener=id->{if(!busy)applyStock(id,false);};filmWheel.reselected=this::showStrength;filmShelf.addView(filmWheel,new LinearLayout.LayoutParams(0,dp(64),1));FilmShelfButton more=new FilmShelfButton(this,true);more.setOnClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);showFilms();});add(filmShelf,more,48,48);add(cameraPage,filmShelf,-1,64);
