    void updateFrameLayout(){
        if(finderStage==null||finder==null||finderStage.getWidth()<=0||finderStage.getHeight()<=0)return;
        int[] size=FrameFormat.fit(frameFormat,finderStage.getWidth(),finderStage.getHeight());FrameLayout.LayoutParams lp=(FrameLayout.LayoutParams)finder.getLayoutParams();
        if(lp.width!=size[0]||lp.height!=size[1]){lp.width=size[0];lp.height=size[1];finder.setLayoutParams(lp);}if(camera!=null)finder.post(()->{if(!destroyed){camera.film=liveSettings();camera.refreshFilm();}});
    }
    void showFrames(){if(busy){toast("请等待拍摄或显影完成");return;}filmGroupButton.finish();filmWheel.finish();lensWheel.finish();new FramePicker(this,frameFormat,id->{if(busy)return;finderTouch.cancel();frameFormat=id;camera.unlockMetering();refreshTools();updateFrameLayout();camera.refreshFilm();persist();}).show();}
    void showExposure(){if(busy){toast("请等待拍摄或显影完成");return;}filmGroupButton.finish();filmWheel.finish();lensWheel.finish();ExposureLimits limits=camera.exposureLimits();if(!limits.supported()){toast("当前镜头尚未就绪或不支持曝光补偿");return;}new ExposurePicker(this,cameraEv,limits,this::applyExposure).show();}
    void applyExposure(float value){ExposureLimits limits=camera.exposureLimits();if(!limits.supported())return;float next=limits.snap(value);if(Math.abs(next-cameraEv)<.0001f)return;cameraEv=next;evButton.set(next);camera.exposure(next);}void saveComposition(){grid=composition.on&&composition.lines==1;prefs.edit().putBoolean("guides_on",composition.on).putInt("guides_lines",composition.lines).putBoolean("guides_cross",composition.cross).putBoolean("guides_level",composition.level).putBoolean("grid",grid).apply();guides.invalidate();refreshTools();if(levels!=null)levels.update();}boolean groupContains(int id){return filmGroup==FilmGroups.FAVORITES?pinnedFilms.contains(id):FilmGroups.contains(filmGroup,id);}
    void refreshStrength(){String label=FilmStrength.percent(settings.strength)+"%";if(filmWheel!=null)filmWheel.strength(settings.strength);if(roomStrengthButton!=null)roomStrengthButton.setText("胶片强度 · "+label);}
    void showStrength(){if(busy||exporting)return;if(activeStrengthPicker!=null&&activeStrengthPicker.isShowing())return;filmGroupButton.finish();filmWheel.finish();lensWheel.finish();StrengthPicker opened=new StrengthPicker(this,FilmCatalog.NAMES[settings.stock],settings.strength,value->{settings.strength=value;syncFilm();});activeStrengthPicker=opened;opened.setOnDismissListener(d->{if(activeStrengthPicker==opened)activeStrengthPicker=null;});opened.show();}
    void updatePins(List<Integer> ids){pinnedFilms=FilterShelf.parse(FilterShelf.encode(ids),true);if(filmGroup==FilmGroups.FAVORITES){if(pinnedFilms.isEmpty())filmGroup=FilmGroups.ALL;else if(!pinnedFilms.contains(settings.stock)){setStock(pinnedFilms.get(0));return;}}refreshStockButtons();persist();}
    void showFavorites(){if(busy)return;if(activeFavoritesPicker!=null&&activeFavoritesPicker.isShowing())return;FavoritesPicker opened=new FavoritesPicker(this,pinnedFilms,this::updatePins);activeFavoritesPicker=opened;opened.setOnDismissListener(d->{if(activeFavoritesPicker==opened)activeFavoritesPicker=null;});opened.show();}
    @Override public void metering(int state,String reason){main.post(()->{if(destroyed)return;boolean active=state!=MeteringLock.IDLE;guides.lock(active);lockButton.setVisibility(active?View.VISIBLE:View.GONE);lockButton.setText(state==MeteringLock.LOCKED?"AE/AF 已锁定  ×":"AE/AF 锁定中…  ×");lockButton.setContentDescription((state==MeteringLock.LOCKED?"对焦和曝光已锁定":"正在锁定对焦和曝光")+"，点击解除");if(!reason.isEmpty())toast(reason);});}
    void showHistogram(){if(busy){toast("请等待拍摄或显影完成");return;}if(activeHistogramPicker!=null&&activeHistogramPicker.isShowing())return;filmGroupButton.finish();filmWheel.finish();lensWheel.finish();histogram.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);HistogramPicker opened=new HistogramPicker(this,histogram,FilmCatalog.NAMES[settings.stock]);activeHistogramPicker=opened;opened.setOnDismissListener(d->{if(activeHistogramPicker==opened)activeHistogramPicker=null;});opened.show();}
    void showLensSources(){openUtility(new UtilitySheet(this,"焦段与光学来源",s->{s.note("长按焦段滚轮可打开本页。裁切档位始终基于对应光学镜头，不用主摄冒充超广角或长焦。");for(float mm:FOCALS){TextView item=s.action(ImageQuality.optical(mm)+(mm==focal?" ✓":""),()->{selectFocal(mm);s.dismiss();});item.setEnabled(camera.available(mm));if(!camera.available(mm))item.setText(ImageQuality.optical(mm)+" · "+camera.unavailableLabel(mm));}}));}
    void selectFocal(float mm){if(busy)return;finderTouch.cancel();if(!camera.available(mm)){toast((int)mm+"mm 需要 "+LensPlan.base(mm)+"mm 光学镜头，当前未开放或不可用");return;}camera.focal(mm);}
    @Override public void lensesChanged(){main.post(this::refreshLensButtons);}
    void refreshLensButtons(){if(camera==null||lensWheel==null)return;if(finderTouch!=null&&(focal!=camera.focal()||camera.exposureLimits()==ExposureLimits.NONE))finderTouch.cancel();focal=camera.focal();ExposureLimits limits=camera.exposureLimits();if(limits.supported()){float applied=limits.snap(cameraEv);if(Math.abs(applied-cameraEv)>.0001f){cameraEv=applied;evButton.set(applied);camera.exposure(applied);}}else if(limits!=ExposureLimits.NONE&&evButton!=null){cameraEv=0;evButton.set(0);}camera.film=liveSettings();camera.refreshFilm();boolean[] available=new boolean[FOCALS.length];String[] labels=new String[FOCALS.length];int actual=1;for(int i=0;i<FOCALS.length;i++){float mm=FOCALS[i];available[i]=!busy&&camera.available(mm);String kind=LensPlan.crop(mm)<1.01?"光学":"×"+String.format(Locale.US,"%.2f",LensPlan.crop(mm));labels[i]=camera.front()?"后置":!camera.scanned()?"检测中":camera.available(mm)?kind:camera.unavailableLabel(mm);if(mm==focal)actual=i;}lensWheel.availability(available,labels,actual,camera.front()||busy);}
    void setStock(int index){applyStock(index,true);}
    void applyStock(int index,boolean align){settings.stock=FilmCatalog.safe(index);if(!groupContains(settings.stock))filmGroup=FilmGroups.family(settings.stock);recentFilms=FilterShelf.remember(recentFilms,settings.stock);prefs.edit().putInt("film_group_last_"+FilmGroups.family(settings.stock),settings.stock).putInt("film_group_last_"+filmGroup,settings.stock).apply();if(align)refreshStockButtons();if(roomStockButton!=null)roomStockButton.setText(Film.NAMES[settings.stock]+"  ▾");syncFilm();}
    void refreshStockButtons(){if(filmWheel!=null){filmWheel.films(FilmGroups.ids(filmGroup,pinnedFilms),settings.stock);filmGroupButton.group(filmGroup,!pinnedFilms.isEmpty());}}
    void selectFilmGroup(int group){if(busy)return;if(group==FilmGroups.FAVORITES&&pinnedFilms.isEmpty()){showFavorites();return;}filmGroup=FilmGroups.safe(group);int remembered=prefs.getInt("film_group_last_"+filmGroup,-1);setStock(FilmGroups.choose(filmGroup,settings.stock,remembered,pinnedFilms));}
    void showFilmGroups(){if(busy){toast("请等待拍摄或显影完成");return;}filmGroupButton.finish();filmWheel.finish();lensWheel.finish();filmGroupButton.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);PopupMenu menu=new PopupMenu(ThemeUi.context(this),filmGroupButton);for(int n=0;n<FilmGroups.LABELS.length;n++){int i=n==0?FilmGroups.FAVORITES:n-1;menu.getMenu().add(0,i,n,FilmGroups.LABELS[i]+" · "+FilmGroups.ids(i,pinnedFilms).size()+" 款").setCheckable(true).setChecked(i==filmGroup);}menu.getMenu().add(1,100,100,"管理收藏排序");menu.getMenu().setGroupCheckable(0,true,true);menu.setOnMenuItemClickListener(item->{if(busy)return true;if(item.getItemId()==100){showFavorites();return true;}selectFilmGroup(item.getItemId());return true;});menu.show();}
    void showFilms(){if(busy){toast("请等待拍摄或显影完成");return;}if(activeFilmPicker!=null&&activeFilmPicker.isShowing())return;filmGroupButton.finish();filmWheel.finish();lensWheel.finish();Film.Settings comparison=page==0?liveSettings():settings.copy();FilmPicker opened=new FilmPicker(this,settings.stock,pinnedFilms,recentFilms,new FilmPicker.Listener(){public void choose(int id){setStock(id);}public void pinsChanged(List<Integer> ids){updatePins(ids);}},page==0?camera:null,page==1?editBase:null,comparison);activeFilmPicker=opened;opened.setOnDismissListener(d->{if(activeFilmPicker==opened)activeFilmPicker=null;});opened.show();}
    void syncFilm(){refreshStrength();Film.Settings live=liveSettings();camera.film=live;camera.refreshFilm();persist();if(page==1&&editBase!=null)renderEdit();}
    void persist(){prefs.edit().putInt("stock",settings.stock).putFloat("skin",settings.skin).putFloat("highlights",settings.highlights).putBoolean("adaptive_grain",settings.adaptiveGrain).putFloat("strength",settings.strength).putInt("film_group",filmGroup).putInt("frame_format",frameFormat).putFloat("cyan",settings.cyan).putFloat("magenta",settings.magenta).putFloat("yellow",settings.yellow).putFloat("grain",settings.grain).putFloat("fade",settings.fade).putBoolean("grid",grid).putInt("shots",shots).putString("film_pins",FilterShelf.encode(pinnedFilms)).putString("film_recent",FilterShelf.encode(recentFilms)).apply();}
    void capture(){
        if(busy||exporting)return;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},1);return;}
        if(finder.getWidth()<=0||finder.getHeight()<=0||finder.isLayoutRequested()){toast("正在调整取景框，请稍候");return;}
        finderTouch.cancel();lensWheel.finish();filmGroupButton.setEnabled(false);filmWheel.setEnabled(false);busy=true;refreshLensButtons();processing=false;shutter.busy=true;shutter.invalidate();shotSettings=liveSettings();shotFrame=new FrameFormat.Snapshot(frameFormat,finder.getWidth(),finder.getHeight());long token=++captureToken;shutter.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);
        if(timer>0)tick(timer,token);else camera.shoot();main.postDelayed(()->{if(busy&&!processing&&captureToken==token){resetShutter();toast("拍摄超时，请重试");}},(timer+(prefs.getBoolean("raw",false)?50:18))*1000L);
    }
    void tick(int n,long token){if(token!=captureToken||!busy)return;if(n<=0){countdown.setText("");camera.shoot();return;}countdown.setText(String.valueOf(n));main.postDelayed(()->tick(n-1,token),1000);}
    void resetShutter(){busy=false;processing=false;filmGroupButton.setEnabled(true);filmWheel.setEnabled(true);refreshLensButtons();countdown.setText("");countdown.setTextSize(48);shutter.busy=false;shutter.invalidate();if(updates!=null)updates.flush();}
    @Override public void status(String s){main.post(()->{if(destroyed)return;status.setText(s.contains(" · 预览 ")?ImageQuality.optical(focal)+" · "+(camera.iso()>0?"ISO "+camera.iso():"取景")+" · "+(prefs.getInt("preview_mode",0)==1?"流畅":"清晰"):s);status.setContentDescription(s);});}
    @Override public void error(String s){main.post(()->{if(destroyed)return;finderTouch.cancel();resetShutter();status.setText(s);toast(s);});}
    @Override public void picture(CameraEngine.Shot shot){
        processing=true;final Film.Settings film=shotSettings==null?liveSettings():shotSettings.copy();film.iso=shot.info==null?0:shot.info.iso;final FrameFormat.Snapshot framing=shotFrame;final float photoAspect=framing==null?0:framing.outputAspect(shot.orientation.device);final String lens=shot.lens+(framing==null?"":" · "+FrameFormat.LABELS[framing.format]+"画幅");main.post(()->{if(destroyed)return;busy=true;shutter.busy=true;shutter.invalidate();countdown.setText("显影中");countdown.setTextSize(22);});
        worker.execute(()->{
            try{String id=new SimpleDateFormat("yyyyMMdd_HHmmss_SSS",Locale.US).format(new Date());File original=new File(rollDir,id+"_original.jpg");try(FileOutputStream o=new FileOutputStream(original)){o.write(shot.jpeg);}
                Bitmap source=decode(original,4096);
                if(shot.clockwise!=0){android.graphics.Matrix rotate=new android.graphics.Matrix();rotate.postRotate(shot.clockwise);Bitmap upright=Bitmap.createBitmap(source,0,0,source.getWidth(),source.getHeight(),rotate,true);if(upright!=source)source.recycle();source=upright;}
                if(shot.crop>1.001f){int[] size=LensPlan.cropSize(source.getWidth(),source.getHeight(),shot.crop);Bitmap cropped=Bitmap.createBitmap(source,(source.getWidth()-size[0])/2,(source.getHeight()-size[1])/2,size[0],size[1]);if(cropped!=source)source.recycle();source=cropped;}
                writeJpeg(source,original,shot.orientation);photoExif(original,shot.info);
                source=cropFrame(source,photoAspect);film.grainEdge=Math.max(source.getWidth(),source.getHeight());Bitmap developed=Film.develop(source,film);source.recycle();File local=new File(rollDir,id+".jpg");writeJpeg(developed,local,shot.orientation);photoExif(local,shot.info);writeMeta(id,Uri.EMPTY,film,lens,shot.orientation,photoAspect);writeCaptureMeta(id,shot,developed.getWidth(),developed.getHeight());String albumMessage="";try{Uri uri=saveMedia(developed,id,shot.orientation);writeMeta(id,uri,film,lens,shot.orientation,photoAspect);if(shot.info!=null)try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"rw")){if(fd!=null)photoExif(new ExifInterface(fd.getFileDescriptor()),shot.info);}}catch(Exception e){albumMessage="内部底片已保存，系统相册保存未完成，可从详情再次显影";}finally{developed.recycle();}
                String rawMessage=shot.rawNote;boolean rawSaved=false;if(shot.dng!=null){File raw=new File(rollDir,id+".dng");try{java.nio.file.Files.copy(shot.dng.toPath(),raw.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);rawSaved=true;JSONObject meta=readMeta(id);meta.put("dng_saved",true);try{meta.put("dng_uri",saveRaw(raw,id).toString());}catch(Exception e){rawMessage="DNG已在内部保存，可从详情导出";}meta.put("raw_note",rawMessage);saveMeta(id,meta);}catch(Exception e){if(!rawSaved)raw.delete();rawMessage=rawSaved?"DNG已保留，参数记录未完成":"JPEG已保存，DNG保存失败："+e.getMessage();}}final String extra=(albumMessage.isEmpty()?"":albumMessage+"\n")+(rawMessage==null?"":rawMessage);final boolean hasRaw=rawSaved;
                main.post(()->{if(destroyed)return;shots++;persist();frameCount.setText(String.format(Locale.US,"%03d",shots));resetShutter();countdown.setTextSize(48);updateLatest(id);toast("已显影并保存"+(hasRaw?" · JPEG + DNG":"")+(extra==null||extra.isEmpty()?"":"\n"+extra));});
            }catch(Throwable e){main.post(()->{if(destroyed)return;resetShutter();toast("保存失败，底片可能已保留："+e.getMessage());});}finally{if(shot.dng!=null)shot.dng.delete();}
        });
    }
    Bitmap decode(File file,int max) throws IOException{return ImageDecoder.decodeBitmap(ImageDecoder.createSource(file),(d,info,src)->{d.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);int w=info.getSize().getWidth(),h=info.getSize().getHeight();if(Math.max(w,h)>max){float scale=max/(float)Math.max(w,h);d.setTargetSize(Math.round(w*scale),Math.round(h*scale));}});}
    Bitmap cropFrame(Bitmap source,float aspect){int[] r=FrameFormat.crop(source.getWidth(),source.getHeight(),aspect);if(r[2]==source.getWidth()&&r[3]==source.getHeight())return source;Bitmap out=Bitmap.createBitmap(source,r[0],r[1],r[2],r[3]);if(out!=source)source.recycle();return out;}
    void writeJpeg(Bitmap b,File f)throws IOException{writeJpeg(b,f,null);}
    void writeJpeg(Bitmap b,File f,CaptureOrientation.Snapshot pose)throws IOException{try(FileOutputStream out=new FileOutputStream(f)){if(!b.compress(Bitmap.CompressFormat.JPEG,96,out))throw new IOException("JPEG 编码失败");}normalizedExif(new ExifInterface(f.getAbsolutePath()),pose);}
    void normalizedExif(ExifInterface exif,CaptureOrientation.Snapshot pose)throws IOException{
        exif.setAttribute(ExifInterface.TAG_ORIENTATION,String.valueOf(ExifInterface.ORIENTATION_NORMAL));exif.setAttribute(ExifInterface.TAG_SOFTWARE,"Fancy Camera");
        exif.setAttribute(ExifInterface.TAG_USER_COMMENT,pose==null?"Fancy Camera; pixels_upright=true":pose.comment());exif.saveAttributes();
    }
    Uri saveMedia(Bitmap bitmap,String name)throws IOException{return saveMedia(bitmap,name,null);}
    Uri saveMedia(Bitmap bitmap,String name,CaptureOrientation.Snapshot pose)throws IOException{
        ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"SR_"+name+".jpg");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Silverroom");values.put(MediaStore.Images.Media.IS_PENDING,1);
        Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("无法创建相册文件");
        try{try(OutputStream os=getContentResolver().openOutputStream(uri)){if(os==null||!bitmap.compress(Bitmap.CompressFormat.JPEG,96,os))throw new IOException("无法写入照片");}
            try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"rw")){if(fd==null)throw new IOException("无法写入照片方向");normalizedExif(new ExifInterface(fd.getFileDescriptor()),pose);}
            values.clear();values.put(MediaStore.Images.Media.IS_PENDING,0);values.put(MediaStore.Images.Media.WIDTH,bitmap.getWidth());values.put(MediaStore.Images.Media.HEIGHT,bitmap.getHeight());values.put(MediaStore.Images.Media.ORIENTATION,0);getContentResolver().update(uri,values,null,null);return uri;
        }catch(IOException e){getContentResolver().delete(uri,null,null);throw e;}
    }
    void writeMeta(String id,Uri uri,Film.Settings s)throws Exception{writeMeta(id,uri,s,"");}
    void writeMeta(String id,Uri uri,Film.Settings s,String lens)throws Exception{writeMeta(id,uri,s,lens,null);}
    void writeMeta(String id,Uri uri,Film.Settings s,String lens,CaptureOrientation.Snapshot pose)throws Exception{writeMeta(id,uri,s,lens,pose,0);}
    void writeMeta(String id,Uri uri,Film.Settings s,String lens,CaptureOrientation.Snapshot pose,float aspect)throws Exception{JSONObject j=readMeta(id);JSONObject values=SettingsCodec.write(s);java.util.Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();j.put(key,values.get(key));}j.put("uri",uri.toString());j.put("stock",s.stock);j.put("strength",FilmStrength.clamp(s.strength));j.put("cyan",s.cyan);j.put("magenta",s.magenta);j.put("yellow",s.yellow);j.put("grain",s.grain);j.put("fade",s.fade);j.put("exposure",s.exposure);j.put("lens",lens);j.put("frame_aspect",aspect);j.put("pixels_upright",true);if(pose!=null){j.put("device_degrees",pose.device);j.put("sensor_degrees",pose.sensor);j.put("capture_rotation",pose.rotation);j.put("front",pose.front);}saveMeta(id,j);}
    void saveMeta(String id,JSONObject j)throws Exception{if(!NegativeStore.valid(id))throw new IOException("Invalid negative ID");File temp=new File(rollDir,id+".json.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}java.nio.file.Files.move(temp.toPath(),new File(rollDir,id+".json").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
    void writeCaptureMeta(String id,CameraEngine.Shot shot,int w,int h)throws Exception{JSONObject j=readMeta(id);j.put("width",w);j.put("height",h);j.put("raw_note",shot.rawNote);j.put("captured_at",shot.capturedAt);j.put("capture_offset_minutes",shot.offsetMinutes);if(shot.info!=null){CaptureInfo i=shot.info;JSONObject actual=new JSONObject();actual.put("iso",i.iso);actual.put("exposure_ns",i.exposure);actual.put("sensor_timestamp",i.timestamp);actual.put("mm",i.mm);actual.put("base",i.base);actual.put("focal_mm",i.physical);actual.put("aperture",i.fNumber);actual.put("ev",i.ev);actual.put("awb",i.awb);actual.put("camera",i.cameraId);actual.put("summary",i.summary());j.put("capture",actual);}saveMeta(id,j);}
    CaptureInfo captureInfo(JSONObject i){return new CaptureInfo(i.optInt("iso"),i.optLong("exposure_ns"),i.optLong("sensor_timestamp"),(float)i.optDouble("mm"),(float)i.optDouble("focal_mm"),(float)i.optDouble("aperture"),(float)i.optDouble("ev"),i.optInt("awb",-1),i.optInt("base"),i.optString("camera",""));}void photoExif(File file,CaptureInfo info)throws IOException{if(info!=null)photoExif(new ExifInterface(file.getAbsolutePath()),info);}
    void photoExif(ExifInterface e,CaptureInfo info)throws IOException{if(info.iso>0)e.setAttribute(ExifInterface.TAG_ISO_SPEED_RATINGS,String.valueOf(info.iso));if(info.exposure>0)e.setAttribute(ExifInterface.TAG_EXPOSURE_TIME,String.valueOf(info.exposure/1e9));if(info.physical>0)e.setAttribute(ExifInterface.TAG_FOCAL_LENGTH,Math.round(info.physical*10000)+"/10000");if(info.fNumber>0)e.setAttribute(ExifInterface.TAG_F_NUMBER,String.valueOf(info.fNumber));e.setAttribute(ExifInterface.TAG_FOCAL_LENGTH_IN_35MM_FILM,String.valueOf(Math.round(info.mm)));e.setAttribute(ExifInterface.TAG_EXPOSURE_BIAS_VALUE,Math.round(info.ev*100)+"/100");e.saveAttributes();}
    Uri saveRaw(File raw,String id)throws IOException{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"FC_"+id+".dng");values.put(MediaStore.Images.Media.MIME_TYPE,"image/x-adobe-dng");values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Silverroom");values.put(MediaStore.Images.Media.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("无法创建DNG");try{try(InputStream in=new FileInputStream(raw);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入DNG");byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1)out.write(block,0,n);}values.clear();values.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(uri,values,null,null);return uri;}catch(Exception e){getContentResolver().delete(uri,null,null);throw new IOException(e);}}
    void refreshLatest(){if(destroyed)return;worker.execute(()->{List<String> ids=NegativeStore.list(rollDir);String id=ids.isEmpty()?null:ids.get(0);main.post(()->{if(!destroyed)updateLatest(id);});});}
    void updateLatest(String id){if(destroyed)return;lastPhotoId=id;int ticket=++lastPhotoToken;if(lastPhoto==null)return;if(id==null){lastPhoto.setImageDrawable(null);return;}thumbs.execute(()->{try{Bitmap image=decode(new File(rollDir,id+".jpg"),120);main.post(()->{if(!destroyed&&ticket==lastPhotoToken)lastPhoto.setImageBitmap(image);else image.recycle();});}catch(Exception ignored){}});}
    void recipeDocument(boolean export){if(export){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"FancyCamera-recipes.json");try{startActivityForResult(intent,EXPORT_RECIPE);}catch(ActivityNotFoundException e){toast("没有可用的文档保存入口");}}else{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/plain"});try{startActivityForResult(intent,IMPORT_RECIPE);}catch(ActivityNotFoundException e){toast("没有可用的文档选择入口");}}}
    String pendingRawExport;
    void recipeResult(int request,Uri uri){worker.execute(()->{String message;try{if(request==IMPORT_RECIPE){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取配方");byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>RecipeStore.MAX_BYTES)throw new IOException("配方文件超过128KB");bytes.write(buffer,0,n);}}int added=new RecipeStore(getFilesDir()).merge(new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));message="已导入 "+added+" 份配方";}else if(request==203){String id=pendingRawExport;if(!NegativeStore.valid(id))throw new IOException("RAW导出已失效，请重试");try(InputStream in=new FileInputStream(new File(rollDir,id+".dng"));OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入RAW");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}message="DNG已导出";}else{String json=new RecipeStore(getFilesDir()).encode(new RecipeStore(getFilesDir()).list());try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入配方");out.write(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));}message="配方库已导出";}}catch(Exception e){message="操作失败："+e.getMessage();}String result=message;main.post(()->toast(result));});}
    void shareRaw(String id){if(!NegativeStore.valid(id))return;JSONObject meta=readMeta(id);String saved=meta.optString("dng_uri","");if(!saved.isEmpty()){Intent share=new Intent(Intent.ACTION_SEND).setType("image/x-adobe-dng").putExtra(Intent.EXTRA_STREAM,Uri.parse(saved)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(share,"分享DNG原片"));}catch(Exception e){toast(e.getMessage());}}else if(new File(rollDir,id+".dng").isFile()){pendingRawExport=id;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/x-adobe-dng").putExtra(Intent.EXTRA_TITLE,id+".dng"),203);}catch(Exception e){toast(e.getMessage());}}else toast("此底片没有DNG原始文件");}
    String awbName(int mode){String[] names={"关闭","自动","白炽灯","荧光灯","暖荧光","日光","多云","黄昏","阴影"};return mode>=0&&mode<names.length?names[mode]:"未返回";}String photoDetails(String id,JSONObject j){JSONObject actual=j.optJSONObject("capture");String info=actual==null?"旧底片未记录实际快门和ISO":actual.optString("summary","")+"\n实际焦距 "+(actual.optDouble("focal_mm",0)>0?actual.optDouble("focal_mm")+"mm":"未返回")+" · 光圈 "+(actual.optDouble("aperture",0)>0?"f/"+actual.optDouble("aperture"):"未返回")+"\n白平衡 "+awbName(actual.optInt("awb",-1))+" · "+actual.optString("camera","");Film.Settings recipe=SettingsCodec.read(j);return (j.optBoolean("capture_inherited",false)?"拍摄参数继承自原底片\n":"")+info+"\n"+j.optString("lens","")+"\n"+(j.optInt("width",0)>0?j.optInt("width")+"×"+j.optInt("height"):"尺寸未记录")+" · "+FilmCatalog.NAMES[recipe.stock]+" · 强度 "+FilmStrength.percent(recipe.strength)+"%\nC/M/Y "+recipe.cyan+" / "+recipe.magenta+" / "+recipe.yellow+"\n颗粒 "+recipe.grain+" · 褪色 "+recipe.fade+" · 肤色 "+recipe.skin+" · 高光 "+recipe.highlights+"\n"+(j.optBoolean("dng_saved",false)?"DNG原始文件已保留":"JPEG底片")+"\n"+j.optString("raw_note","");}
    CaptureOrientation.Snapshot readPose(String id){if(id==null)return null;JSONObject j=readMeta(id);return j.has("device_degrees")?new CaptureOrientation.Snapshot(j.optInt("sensor_degrees",90),j.optInt("device_degrees",0),j.optBoolean("front",false)):null;}
    JSONObject readMeta(String id){try{return new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(rollDir,id+".json").toPath()),java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){return new JSONObject();}}
    void toast(String s){if(!destroyed)Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    void switchPage(int index){
        if(index==page)return;if(busy){toast("正在拍摄或显影，请稍候");return;}finderTouch.cancel();if(page==2)galleryVersion++;filmGroupButton.finish();filmWheel.finish();lensWheel.finish();if(page==0&&resumed){controlRotation.finish();camera.removeHistogram(histogram);camera.pause();}page=index;
        cameraPage.setVisibility(index==0?View.VISIBLE:View.GONE);darkPage.setVisibility(index==1?View.VISIBLE:View.GONE);galleryPage.setVisibility(index==2?View.VISIBLE:View.GONE);
        if(index==0&&resumed){controlRotation.turn(camera.deviceOrientation(),false);camera.histogram(histogram);camera.resume();}if(index==1){refreshRoomControls();renderEdit();}if(index==2)refreshGallery();updateNav();if(levels!=null)levels.update();
    }
    void updateNav(){for(int i=0;i<pageButtons.length;i++){TextView t=pageButtons[i];t.setTextColor(i==page?AMBER:MUTED);t.setBackground(bg(i==page?PANEL:INK,10,0));}}
    @Override protected void onStart(){super.onStart();if(updates!=null)updates.foreground(updateTrigger.enter(updates.automaticEnabled()));}
    @Override protected void onStop(){if(updates!=null)updates.background();updateTrigger.leave();super.onStop();}
    @Override public void startActivityForResult(Intent intent,int requestCode,Bundle options){updateTrigger.external();super.startActivityForResult(intent,requestCode,options);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){ThemeUi.bars(getWindow());if(updates!=null)updates.flush();}}
    @Override protected void onResume(){super.onResume();updateTrigger.resume();resumed=true;if(page==0&&(activePhotoViewer==null||!activePhotoViewer.isShowing())){controlRotation.turn(camera.deviceOrientation(),false);camera.histogram(histogram);camera.resume();}if(levels!=null)levels.update();if(activePrint!=null)activePrint.resumePreview();if(updates!=null)updates.flush();}
    @Override protected void onPause(){controlRotation.finish();if(activePrint!=null)activePrint.pausePreview();finderTouch.cancel();if(levels!=null)levels.stop();if(appSettings!=null)appSettings.dismiss();if(activeUtility!=null)activeUtility.dismiss();if(activeFilmPicker!=null)activeFilmPicker.dismiss();if(activeStrengthPicker!=null)activeStrengthPicker.dismiss();if(activeFavoritesPicker!=null)activeFavoritesPicker.dismiss();if(activeHistogramPicker!=null)activeHistogramPicker.dismiss();filmGroupButton.finish();filmWheel.finish();lensWheel.finish();resumed=false;if(page==0){camera.removeHistogram(histogram);camera.pause();}if(busy&&!processing){captureToken++;resetShutter();}super.onPause();}
    @Override protected void onDestroy(){destroyed=true;if(activePrint!=null)activePrint.dismiss();if(levels!=null)levels.stop();if(renderTask!=null)main.removeCallbacks(renderTask);if(updates!=null)updates.close();galleryVersion++;if(activePhotoViewer!=null)activePhotoViewer.dismiss();thumbs.shutdownNow();camera.destroy();worker.shutdown();super.onDestroy();}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)camera.permission();else{status.setText("相机权限未开启 · 暗房仍可导入照片");toast("可在系统设置中允许相机权限");}}
    @Override public void onBackPressed(){if(page==2&&selectingNegatives){selectingNegatives=false;selectedNegatives.clear();refreshNegativeSelection();}else if(page!=0)switchPage(0);else super.onBackPressed();}
