    void refreshRoomControls(){refreshStrength();if(colorDials[0]==null)return;updatingRoom=true;colorDials[0].set(settings.cyan*100);colorDials[1].set(settings.magenta*100);colorDials[2].set(settings.yellow*100);grainBar.setProgress(Math.round(settings.grain*100));fadeBar.setProgress(Math.round(settings.fade*100));exposureBar.setProgress(Math.round(settings.exposure*100)+200);roomStockButton.setText(Film.NAMES[settings.stock]+"  ▾");updatingRoom=false;}
    void importPhoto(){
        Intent picker=new Intent(MediaStore.ACTION_PICK_IMAGES).setType("image/*");if(Build.VERSION.SDK_INT>=35)picker.putExtra(MediaStore.EXTRA_PICK_IMAGES_LAUNCH_TAB,MediaStore.PICK_IMAGES_TAB_IMAGES);
        try{startActivityForResult(picker,IMPORT);}catch(ActivityNotFoundException|SecurityException unavailable){try{Intent album=new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType("image/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(album,IMPORT);}catch(ActivityNotFoundException|SecurityException missing){toast("没有找到可用的系统相册，请检查系统相册是否启用");}}
    }
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if((r==IMPORT_RECIPE||r==EXPORT_RECIPE||r==203)&&result==RESULT_OK&&data!=null&&data.getData()!=null){recipeResult(r,data.getData());return;}if(r==IMPORT&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();worker.execute(()->{try{File f=new File(getFilesDir(),"import_"+System.currentTimeMillis()+".img");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("无法读取照片");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}loadEdit(f,null);}catch(Throwable e){main.post(()->toast("导入失败："+e.getMessage()));}});}}
    void loadEdit(File original,String id){try{JSONObject meta=id==null?new JSONObject():readMeta(id);final float aspect=(float)meta.optDouble("frame_aspect",0);final Bitmap b=cropFrame(decode(original,1400),aspect);final float priorExposure=(float)meta.optDouble("exposure",0);android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(original.getAbsolutePath(),bounds);int orientation=1;try{orientation=new ExifInterface(original.getAbsolutePath()).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);}catch(IOException ignored){}boolean swapped=orientation==5||orientation==6||orientation==7||orientation==8;final int grainEdge=ImageQuality.editEdge(Math.max(1,swapped?bounds.outHeight:bounds.outWidth),Math.max(1,swapped?bounds.outWidth:bounds.outHeight),aspect);main.post(()->{if(destroyed){b.recycle();return;}editOriginal=original;editId=id;editBase=b;editAspect=aspect;roomLabel.setVisibility(View.GONE);settings.exposure=priorExposure;settings.grainEdge=grainEdge;editGrainEdge=grainEdge;refreshRoomControls();renderEdit();});}catch(Throwable e){main.post(()->toast("无法打开底片："+e.getMessage()));}}
    void renderEdit(){if(destroyed||editBase==null)return;final int version=++editVersion;final Bitmap input=editBase;final Film.Settings film=settings.copy();film.grainEdge=editGrainEdge;main.removeCallbacks(renderTask);renderTask=()->{if(destroyed)return;worker.execute(()->{if(version!=editVersion)return;try{Bitmap result=Film.develop(input,film);main.post(()->{if(version==editVersion&&!destroyed)darkImage.setImageBitmap(result);else result.recycle();});}catch(Throwable e){main.post(()->toast("预览显影失败："+e.getMessage()));}});};main.postDelayed(renderTask,90);}
    Runnable renderTask=()->{};
    void exportEdit(){
        if(editOriginal==null){toast("请先导入照片，或从底片页选择原片");return;}if(exporting)return;
        exporting=true;saveButton.setText("正在显影…");saveButton.setEnabled(false);
        final File source=editOriginal;final Film.Settings film=settings.copy();final String sourceId=editId;final JSONObject origin=sourceId==null?new JSONObject():readMeta(sourceId);final String originLens=editId==null?"导入照片":origin.optString("lens","");final CaptureOrientation.Snapshot pose=readPose(editId);final float aspect=editAspect;
        worker.execute(()->{
            try{Bitmap b=cropFrame(decode(source,4096),aspect);film.grainEdge=Math.max(b.getWidth(),b.getHeight());Bitmap out=Film.develop(b,film);b.recycle();String id=new SimpleDateFormat("yyyyMMdd_HHmmss_SSS",Locale.US).format(new Date());
                java.nio.file.Files.copy(source.toPath(),new File(rollDir,id+"_original.jpg").toPath());writeJpeg(out,new File(rollDir,id+".jpg"),pose);writeMeta(id,Uri.EMPTY,film,originLens,pose,aspect);
                int outputWidth=out.getWidth(),outputHeight=out.getHeight();Uri uri=saveMedia(out,id,pose);out.recycle();writeMeta(id,uri,film,originLens,pose,aspect);JSONObject metadata=readMeta(id);metadata.put("width",outputWidth);metadata.put("height",outputHeight);for(String key:new String[]{"captured_at","capture_offset_minutes","source_datetime","imported"})if(origin.has(key))metadata.put(key,origin.get(key));if(sourceId==null||originLens.contains("导入")){metadata.put("imported",true);try{String date=new ExifInterface(source.getAbsolutePath()).getAttribute(ExifInterface.TAG_DATETIME_ORIGINAL);if(PrintMetadata.validDate(date))metadata.put("source_datetime",date);}catch(Exception ignored){}}if(origin.has("capture")){metadata.put("capture",origin.getJSONObject("capture"));metadata.put("capture_inherited",true);CaptureInfo inherited=captureInfo(origin.getJSONObject("capture"));photoExif(new File(rollDir,id+".jpg"),inherited);try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"rw")){if(fd!=null)photoExif(new ExifInterface(fd.getFileDescriptor()),inherited);}}saveMeta(id,metadata);
                main.post(()->{if(destroyed)return;shots++;persist();frameCount.setText(String.format(Locale.US,"%03d",shots));updateLatest(id);toast("显影完成 · 已保存到系统相册");});
            }catch(Throwable e){main.post(()->toast("显影保存失败："+e.getMessage()));}
            finally{main.post(()->{if(destroyed)return;exporting=false;saveButton.setEnabled(true);saveButton.setText("显影并保存");});}
        });
    }
